using System;using System.IO;using System.Drawing;using System.Drawing.Drawing2D;using System.Drawing.Imaging;using System.Collections.Generic;
class BuildBellIcon{static void Main(string[]args){var images=new List<byte[]>();int[]sizes={16,24,32,48,64,128,256};foreach(int size in sizes){using(var bitmap=new Bitmap(size,size))using(var g=Graphics.FromImage(bitmap)){g.SmoothingMode=SmoothingMode.AntiAlias;g.ScaleTransform(size/256f,size/256f);g.Clear(Color.Transparent);using(var b=new SolidBrush(Color.FromArgb(16,38,61)))g.FillEllipse(b,4,4,248,248);using(var bell=new SolidBrush(Color.FromArgb(255,191,60))){var shape=new GraphicsPath();shape.StartFigure();shape.AddBezier(51,163,70,147,61,99,89,88);shape.AddBezier(89,88,118,72,146,92,146,122);shape.AddBezier(146,122,144,148,154,156,163,163);shape.CloseFigure();g.FillPath(bell,shape);g.FillRectangle(bell,49,163,116,12);g.FillEllipse(bell,94,176,26,17);g.FillEllipse(bell,98,72,16,19);}using(var white=new Pen(Color.White,12)){white.StartCap=white.EndCap=LineCap.Round;g.DrawLines(white,new[]{new Point(156,139),new Point(191,139),new Point(210,159),new Point(210,193)});g.DrawLine(white,175,194,220,194);}using(var gold=new Pen(Color.FromArgb(255,191,60),9)){gold.StartCap=gold.EndCap=LineCap.Round;g.DrawArc(gold,119,47,66,69,280,70);g.DrawArc(gold,119,30,96,104,280,65);}using(var stream=new MemoryStream()){bitmap.Save(stream,ImageFormat.Png);images.Add(stream.ToArray());}if(size==256)bitmap.Save(args[1],ImageFormat.Png);}}
 using(var writer=new BinaryWriter(File.Create(args[0]))){writer.Write((short)0);writer.Write((short)1);writer.Write((short)sizes.Length);int offset=6+16*sizes.Length;for(int i=0;i<sizes.Length;i++){writer.Write((byte)(sizes[i]==256?0:sizes[i]));writer.Write((byte)(sizes[i]==256?0:sizes[i]));writer.Write((short)0);writer.Write((short)1);writer.Write((short)32);writer.Write(images[i].Length);writer.Write(offset);offset+=images[i].Length;}foreach(var image in images)writer.Write(image);}
}}
